-- Gamatex MBTI: 70 soal berdasarkan MBTI V2,1 Open.xlsx
-- Jalankan setelah migrasi question_bank/test_settings tersedia.

begin;

delete from public.question_bank where test_code = 'mbti';


select 'mbti', 'MBTI', true, coalesce(max(sort_order),0)+1, null, now() from public.test_settings
on conflict (test_code) do update set display_name=excluded.display_name, updated_at=now();

commit;
